export const WORKBENCH_TRANSLATION_COVERAGE = Object.freeze(
  Object.fromEntries(
    Object.entries(WORKBENCH_TRANSLATION_OVERRIDES).map(([locale, values]) => [
      locale,
      { translated: Object.keys(values).length, total: Object.keys(english).length },
    ]),
  ) as Record<AdditionalWorkbenchLocale, { translated: number; total: number }>,
);

export function workbenchText(
  locale: AuthLocale,
  key: WorkbenchCopyKey,
  variables: Record<string, string | number> = {},
): string {
  if (key === "switchLanguageLabel") {
    if (locale !== "zh-CN" && locale !== "en") {
      return WORKBENCH_TRANSLATION_OVERRIDES[locale].switchLanguageLabel ?? english[key];
    }
    return locale === "en" ? "Choose language" : "选择语言";
  }
  const template =
    locale === "zh-CN" || locale === "en"
      ? copy[locale][key]
      : WORKBENCH_TRANSLATION_OVERRIDES[locale][key] ?? english[key];
  return Object.entries(variables).reduce(
    (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
    template,
  );
}

export const WORKBENCH_COPY_KEYS = Object.freeze(
  Object.keys(english) as WorkbenchCopyKey[],
);
